        {
          "kind": "metric",
          "sql": "SELECT attr_k8s_pod_name pod, metric, count(*) n, round(avg(value),2) v, min(value) mn, max(value) mx FROM abnormal_metrics WHERE metric = 'k8s.container.ready' AND attr_k8s_pod_name LIKE 'user%' GROUP BY ALL",
          "claim": "The user pod's container ready metric is 0 across the entire abnormal window, versus 1 in normal."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, count(*) n FROM abnormal_traces WHERE service_name = 'user' GROUP BY ALL",
          "claim": "The user service emits no spans during the abnormal window, although it produced 540 spans in normal."
        },
        {
          "kind": "trace",
          "sql": "SELECT c.service_name caller, c.span_name, c.attr_status_code, count(*) n, sum(CASE WHEN p.attr_status_code='Error' THEN 1 ELSE 0 END) parent_500 FROM abnormal_traces c LEFT JOIN abnormal_traces p ON c.parent_span_id = p.span_id AND c.trace_id=p.trace_id WHERE c.span_name LIKE 'user.User/%' GROUP BY ALL",
          "claim": "All 194 frontend calls to user.User/CheckUser end in Error, and each one's parent is a frontend 500."
        }
      ]
    }
  ],
