    {
      "from": "user",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name, p.span_name, p.attr_http_response_status_code, count(*) n FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id = p.span_id AND c.trace_id = p.trace_id WHERE c.span_name = 'user.User/CheckUser' AND c.attr_status_code = 'Error' GROUP BY ALL",
          "claim": "Failed user CheckUser calls surface as frontend HTTP 500s on /cinema, /museums, /restaurants, /reservation and /user."
